75	    /** Request header carrying the client-supplied key that makes a create idempotent. */
76	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
77	
78	    /**
79	     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
80	     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
81	     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
82	     */
83	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
84	
85	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
86	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
87	
88	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
90	        "mailinator.com", "tempmail.com", "guerrillamail.com");
