132	    /**
133	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
134	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
135	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
136	     */
137	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return onFound.apply(owner);
143	    }
