145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
148	        String idempotencyKey = currentIdempotencyKey();
149	        if (idempotencyKey != null) {
150	            Integer existingId = idempotentCreates.get(idempotencyKey);
151	            if (existingId != null) {
152	                Owner existing = this.clinicService.findOwnerById(existingId);
153	                if (existing != null) {
154	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
155	                }
156	            }
157	        }
158	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
159	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
160	                && response.getBody() != null && response.getBody().getId() != null) {
161	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
162	        }
163	        return response;
164	    }
165	
166	    /**
167	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
168	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
169	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
170	     */
171	    private static String currentIdempotencyKey() {
172	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
173	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
174	            if (key != null && !key.isBlank()) {
175	                return key;
176	            }
177	        }
178	        return null;
179	    }
180	
181	    /**
182	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
183	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
184	     * identity and per-city gates are applied, the derived registration attributes are
185	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
186	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
187	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
188	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
189	     * of the create pipeline.
190	     */
191	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
192	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
193	        if (!normalizeAndValidateFields(owner)) {
194	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
195	        }
196	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
197	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
198	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
199	        }
200	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
201	        owner.setRegistrationDate(registrationDate);
202	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
203	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
204	        }
205	        owner.setHouseholdId(householdId(owner));
206	        owner.setIdentityKey(identityKey(owner));
207	        if (isDuplicate(owner)) {
208	            return new ResponseEntity<>(HttpStatus.CONFLICT);
209	        }
210	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
211	        if (countOwnersInCity(owner.getCity()) >= 50) {
212	            return new ResponseEntity<>(HttpStatus.CONFLICT);
213	        }
214	        assignRegistrationAttributes(owner, sharesHousehold);
215	        this.clinicService.saveOwner(owner);
216	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
217	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
218	            owner.getMembershipNumber());
219	        HttpHeaders headers = new HttpHeaders();
220	        headers.setLocation(UriComponentsBuilder.newInstance()
221	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
222	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
223	    }
224	
225	    /**
226	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
227	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
228	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
229	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
230	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
231	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
232	     */
233	    private boolean normalizeAndValidateFields(Owner owner) {
234	        if (!normalizeAddressFields(owner)) {
235	            return false;
236	        }
237	        if (owner.getEmail() != null) {
238	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
239	            if (!EMAIL_PATTERN.matcher(email).matches()) {
240	                return false;
241	            }
242	            if (isDisposableEmailDomain(email)) {
243	                return false;
244	            }
245	            owner.setEmail(email);
246	        }
247	        if (!isPostcodeValidForCity(owner)) {
248	            return false;
249	        }
250	        String telephone = normalizeTelephone(owner.getTelephone());
251	        if (telephone == null) {
252	            return false;
253	        }
254	        owner.setTelephone(telephone);
255	        return true;
256	    }
257	
258	    /**
259	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
260	     * returning whether the owner may proceed to creation. The structured fields are preferred when
261	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
262	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
263	     * composed value (the normalized addressLine1, with a single space and the normalized
264	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
265	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
266	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
267	     * address. This is the single place the owner's address is read, canonicalized and written back,
268	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
269	     */
270	    private boolean normalizeAddressFields(Owner owner) {
271	        String line1 = normalizeAddress(owner.getAddressLine1());
272	        if (!line1.isEmpty()) {
273	            String line2 = normalizeAddress(owner.getAddressLine2());
274	            owner.setAddressLine1(line1);
275	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
276	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
277	            return true;
278	        }
279	        String address = normalizeAddress(owner.getAddress());
280	        if (address.isEmpty()) {
281	            return false;
282	        }
283	        owner.setAddress(address);
284	        return true;
285	    }
286	
287	    /**
288	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
289	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
290	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
291	     */
292	    private static boolean isDisposableEmailDomain(String email) {
293	        int at = email.lastIndexOf('@');
294	        if (at < 0) {
295	            return false;
296	        }
297	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
298	    }
