300	    /**
301	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
302	     * computed against the owner population rather than carried on the owner itself (currently the
303	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
304	     * listing intentionally omits these flags.
305	     */
306	    private OwnerDto buildOwnerDto(Owner owner) {
307	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
308	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
309	        return ownerDto;
310	    }
