330	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
331	            }
332	        }
333	        currentOwner.setEmail(email);
334	        this.clinicService.saveOwner(currentOwner);
335	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
