414	    /** Matches a well-formed postcode: exactly 4 digits. */
415	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
416	
417	    /**
418	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
419	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
420	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
421	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
422	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
423	     */
424	    private static boolean isPostcodeValidForCity(Owner owner) {
425	        String postcode = owner.getPostcode();
426	        if (postcode == null) {
427	            return true;
428	        }
429	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
430	            return false;
431	        }
432	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
433	        if (range == null) {
434	            return true;
435	        }
436	        int value = Integer.parseInt(postcode);
437	        return value >= range[0] && value <= range[1];
438	    }
439	
440	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
441	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
442	
443	    /**
444	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
445	     * code are kept when present; otherwise country code '+61' is assumed and a single
446	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
447	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
448	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
449	     * Returns {@code null} when the number cannot form a valid E.164 value.
450	     */
451	    private static String normalizeTelephone(String telephone) {
452	        if (telephone == null) {
453	            return null;
454	        }
455	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
456	        String e164;
457	        if (cleaned.startsWith("+")) {
458	            e164 = cleaned;
459	        } else {
460	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
461	            e164 = "+61" + national;
462	        }
463	        if (!E164_PATTERN.matcher(e164).matches()) {
464	            return null;
465	        }
466	        return hasValidNationalNumberLength(e164) ? e164 : null;
467	    }
468	
469	    /**
470	     * Whether the national number of a well-formed E.164 value has the length required for its
471	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
472	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
473	     */
474	    private static boolean hasValidNationalNumberLength(String e164) {
475	        String countryCode = Owner.countryCodeOf(e164);
476	        if (countryCode == null) {
477	            return true;
478	        }
479	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
480	    }
481	
482	    /**
483	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
484	     * code, membership number, household id, namesake count and household member count. Each is
485	     * derived from the owner's already-normalized fields and the existing owner population, so this
486	     * must run before the owner is saved, while the counts still exclude the owner being created.
487	     *
488	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
489	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
490	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
491	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
492	     */
493	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
494	        owner.setCustomerCode(generateCustomerCode(owner));
495	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
496	        owner.setHouseholdId(householdId(owner));
497	        owner.setNamesakeCount(countNamesakes(owner));
498	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
499	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
500	        if (declaredMember) {
501	            owner.setPossibleDuplicate(false);
502	            owner.setPossibleDuplicateOf(null);
503	        } else {
504	            assignPossibleDuplicate(owner);
505	        }
506	    }
507	
508	    /**
509	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
510	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
511	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
512	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
513	     * to the matching owner's id. Runs before save, against the existing owner population.
514	     */
515	    private void assignPossibleDuplicate(Owner owner) {
516	        Integer matchId = findPossibleDuplicateOf(owner);
517	        owner.setPossibleDuplicate(matchId != null);
518	        owner.setPossibleDuplicateOf(matchId);
519	    }
520	
521	    /**
522	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
523	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
524	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
525	     * never matches.
526	     */
527	    private Integer findPossibleDuplicateOf(Owner owner) {
528	        String postcode = owner.getPostcode();
529	        if (postcode == null) {
530	            return null;
531	        }
532	        String lastName = normalizeHouseholdField(owner.getLastName());
533	        String telephone = owner.getTelephone();
534	        return this.clinicService.findAllOwners().stream()
535	            .filter(existing -> !existing.isDeleted())
536	            .filter(existing -> existing.getId() != null
537	                && postcode.equals(existing.getPostcode())
538	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
539	                && !telephone.equals(existing.getTelephone()))
540	            .map(Owner::getId)
541	            .min(Integer::compareTo)
542	            .orElse(null);
543	    }
544	
545	    /**
546	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
547	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
548	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
549	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
550	     * region and the (telephone, last name) pair; only when the computed code collides with an
551	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
552	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
553	     */
554	    private String generateCustomerCode(Owner owner) {
555	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
556	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
557	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
558	        String base = owner.getRegion() + "-" + hash8;
559	        return deduplicateCustomerCode(base);
560	    }
561	
562	    /**
563	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
564	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
565	     * {@code n} of 2 or more that yields a code no existing owner carries.
566	     */
567	    private String deduplicateCustomerCode(String base) {
568	        Set<String> existing = this.clinicService.findAllOwners().stream()
569	            .map(Owner::getCustomerCode)
570	            .filter(code -> code != null)
571	            .collect(java.util.stream.Collectors.toSet());
572	        if (!existing.contains(base)) {
573	            return base;
574	        }
575	        int n = 2;
576	        while (existing.contains(base + "-" + n)) {
577	            n++;
578	        }
579	        return base + "-" + n;
580	    }
581	
582	    /**
583	     * The number of existing owners registered in {@code city}, compared case-insensitively
584	     * with collapsed whitespace.
585	     */
586	    private int countOwnersInCity(String city) {
587	        String normalized = normalizeHouseholdField(city);
588	        return (int) this.clinicService.findAllOwners().stream()
589	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
590	            .count();
591	    }
592	
593	    /**
594	     * The effective registration date to store for a new owner: the date supplied on the request
595	     * when present, otherwise the current server date, in either case rolled forward to a business
596	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
597	     * This single point of resolution is what every registration-date-derived value (the stored
598	     * date, the membership number's year segment, the per-day create-limit) is computed from.
599	     */
600	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
601	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
602	        return toBusinessDay(date);
603	    }
604	
605	    /**
606	     * The fixed list of public holidays that a registration date must not fall on. A date landing
607	     * on one of these is rolled forward, exactly as weekends are.
608	     */
609	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
610	        LocalDate.of(2026, 1, 1),
611	        LocalDate.of(2026, 1, 26),
612	        LocalDate.of(2026, 4, 25),
613	        LocalDate.of(2026, 12, 25),
614	        LocalDate.of(2026, 12, 28));
615	
616	    /**
617	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
618	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
619	     * unchanged.
620	     */
621	    private static LocalDate toBusinessDay(LocalDate date) {
622	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
623	                || PUBLIC_HOLIDAYS.contains(date)) {
624	            date = date.plusDays(1);
625	        }
626	        return date;
627	    }
628	
629	    /**
630	     * Build the membership number '<customerCode>-M<YY>' where YY is the
631	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
632	     * (e.g. 'NSW-1A2B3C4D-M27').
633	     */
634	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
635	        return customerCode + "-M" + membershipYearSegment(registrationDate);
636	    }
637	
638	    /**
639	     * The two-digit year segment stamped into a membership number: the last two digits of the
640	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
641	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
642	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
643	     */
644	    private static String membershipYearSegment(LocalDate registrationDate) {
645	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
646	    }
647	
648	    /**
649	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
650	     * last name, compared case-insensitively.
651	     */
652	    private int countNamesakes(Owner owner) {
653	        String firstName = normalizeHouseholdField(owner.getFirstName());
654	        String lastName = normalizeHouseholdField(owner.getLastName());
655	        return (int) this.clinicService.findAllOwners().stream()
656	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
657	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
658	            .count();
659	    }
660	
661	    /**
662	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
663	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
664	     * unusually high daily signup volume.
665	     */
666	    private boolean isBulkSignupWarning() {
667	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
668	    }
669	
670	    /** The number of existing owners whose registration date is {@code date}. */
671	    private int countOwnersRegisteredOn(LocalDate date) {
672	        return (int) this.clinicService.findAllOwners().stream()
673	            .filter(existing -> date.equals(existing.getRegistrationDate()))
674	            .count();
675	    }
676	
677	    /**
678	     * The single derived key all duplicate detection flows through, formed from the owner's
679	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
680	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
681	     * id is derived, so the household segment is empty at that point. Because the telephone is part
682	     * of the key, two owners in the same household with different telephones resolve to different
683	     * keys and are both allowed.
684	     */
685	    private static String identityKey(Owner owner) {
686	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
687	        String email = owner.getEmail() == null ? "" : owner.getEmail();
688	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
689	        return telephone + "|" + email + "|" + household;
690	    }
691	
692	    /**
693	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
694	     * duplicate condition: the previously separate telephone, email and household checks are now all
695	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
696	     * trips it is rejected with {@code 409 CONFLICT}.
697	     */
698	    private boolean isDuplicate(Owner owner) {
699	        String key = owner.getIdentityKey();
700	        return this.clinicService.findAllOwners().stream()
701	            .filter(existing -> !existing.isDeleted())
702	            .map(Owner::getIdentityKey)
703	            .filter(existing -> existing != null)
704	            .anyMatch(key::equals);
705	    }
706	
707	    /** Common street-type abbreviations expanded during address normalization. */
708	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
709	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
710	
711	    /**
712	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
713	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
714	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
715	     * string when {@code address} is null or blank after normalization.
716	     */
717	    private static String normalizeAddress(String address) {
718	        if (address == null) {
719	            return "";
720	        }
721	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
722	        if (collapsed.isEmpty()) {
723	            return "";
724	        }
725	        StringBuilder sb = new StringBuilder(collapsed.length());
726	        for (String token : collapsed.split(" ")) {
727	            if (sb.length() > 0) {
728	                sb.append(' ');
729	            }
730	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
731	        }
732	        return sb.toString();
733	    }
734	
735	    /**
736	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
737	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
738	     */
739	    private static String normalizeHouseholdField(String value) {
740	        if (value == null) {
741	            return "";
742	        }
743	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
744	    }
745	
746	    /**
747	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
748	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
749	     * key rather than re-derived from the underlying fields here, so the household is described in one
750	     * place and every household-keyed value stays consistent with it.
751	     */
752	    private List<Owner> findHousemates(Owner owner) {
753	        String householdId = householdId(owner);
754	        return this.clinicService.findAllOwners().stream()
755	            .filter(existing -> !existing.isDeleted())
756	            .filter(existing -> householdId(existing).equals(householdId))
757	            .toList();
758	    }
759	
760	    /**
761	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
762	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
763	     */
764	    private int countHouseholdMembers(Owner owner) {
765	        return findHousemates(owner).size() + 1;
766	    }
767	
768	    /**
769	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
770	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
771	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
772	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
773	     * applies - when the owner has no existing household member.
774	     */
775	    private Integer membershipLevelCapForHousehold(Owner owner) {
776	        OptionalInt maxLevel = findHousemates(owner).stream()
777	            .mapToInt(Owner::getMembershipLevel)
778	            .max();
779	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
780	    }
781	
782	    /**
783	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
784	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
785	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
786	     * string standing in for a missing postcode), so housemates always resolve to the same value
787	     * regardless of registration order, and owners sharing a last name and postcode share it
788	     * automatically.
789	     */
790	    private static String householdId(Owner owner) {
791	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
792	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
793	        return sha256Hex(key).substring(0, 12);
794	    }
795	
796	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
797	    private static String sha256Hex(String input) {
798	        try {
799	            byte[] digest = MessageDigest.getInstance("SHA-256")
800	                .digest(input.getBytes(StandardCharsets.UTF_8));
801	            StringBuilder sb = new StringBuilder(digest.length * 2);
802	            for (byte b : digest) {
803	                sb.append(String.format("%02X", b));
804	            }
805	            return sb.toString();
806	        }
807	        catch (NoSuchAlgorithmException e) {
808	            throw new IllegalStateException("SHA-256 not available", e);
809	        }
810	    }
811	}
