27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "postcode")
56	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
57	    private String postcode;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    private String email;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "identity_key")
80	    private String identityKey;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "household_member_count")
86	    private Integer householdMemberCount;
87	
88	    @Column(name = "membership_number")
89	    private String membershipNumber;
90	
91	    @Column(name = "membership_level_cap")
92	    private Integer membershipLevelCap;
93	
94	    @Column(name = "possible_duplicate")
95	    private Boolean possibleDuplicate;
96	
97	    @Column(name = "possible_duplicate_of")
98	    private Integer possibleDuplicateOf;
99	
100	    @Column(name = "deleted", nullable = false)
101	    private boolean deleted;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
